// publishes for its International Mathematics Olympiad (sofworld.org/imo, checked 16 Nov 2026); no question is taken
// from an SOF paper, sample paper or any other paper.
//
// Row: [chapter, topic, difficulty (E/M/H), English prompt, English options, English explanation,
//       Hindi prompt, Hindi options (null = same as English), Hindi explanation, verify?]
// The FIRST option is always the correct one; the builder moves it to a balanced position. `verify`, when given, is
// recomputed by the builder and must equal the first option, so computed answers are checked by machine.
const n = (x) => Number(x).toLocaleString('en-IN');
const gcd = (a, b) => (b ? gcd(b, a % b) : a);
const lcm = (...v) => v.reduce((a, b) => (a * b) / gcd(a, b));
const isPrime = (k) => k > 1 && [...Array(Math.floor(Math.sqrt(k)) + 1).keys()].slice(2).every((d) => k % d);
const count = (lo, hi, ok) => { let c = 0; for (let i = lo; i <= hi; i++) if (ok(i)) c++; return c; };
const modpow = (b, e, m) => { let r = 1; b %= m; while (e) { if (e & 1) r = (r * b) % m; b = (b * b) % m; e >>= 1; } return r; };
const divisors = (k) => [...Array(k).keys()].map((i) => i + 1).filter((d) => k % d === 0);

